// Extract & Group — tools: zaproxy, trufflehog, securityhub, checkov, prowler, kubescape
// Reads selected tool from Set node "Config" (cfg.tool)
// Input: Jira Search items (each item.json.fields.description may be ADF)
// Output: grouped items with combined* fields + sourceIssueKeys

// ---------- config ----------
const cfg  = $items('Config')?.[0]?.json || {};
const tool = String(cfg.tool || 'zaproxy').toLowerCase();

// ---------- helpers ----------
function safeReplaceAll(s, f, r){ return String(s).split(f).join(r); }
function cleanText(s){
  if (s == null) return s;
  s = String(s);
  const repl = { "&quot;":'"',"&#x27;":"'", "&amp;":"&","&#x2F;":"/","&lt;":"<","&gt;":">","&#34;":'"',"&#39;":"'","&#44;":",","&#46;":".","&#58;":":","&#59;":";","&#63;":"?" };
  for (const [k,v] of Object.entries(repl)) s = safeReplaceAll(s,k,v);
  return s.replace(/\s+/g," ").trim();
}
function isUrlLike(s){ return !!(s && /^https?:\/\//i.test(s)); }
function adfToText(node){
  if (!node) return "";
  if (typeof node !== "object") return String(node || "");
  const out=[];
  function txt(n){ let t=n.text||""; for (const m of (n.marks||[])) if (m?.type==="link"){ const href=m.attrs?.href||""; if (href && !isUrlLike(t)) t=href; } return t; }
  function walk(n){
    const t=n.type;
    if (t==="doc"){ (n.content||[]).forEach(walk); return; }
    if (t==="paragraph"){ (n.content||[]).forEach(walk); out.push("\n"); return; }
    if (t==="text"){ out.push(txt(n)); return; }
    if (t==="hardBreak"){ out.push("\n"); return; }
    if (t==="bulletList"||t==="orderedList"){ (n.content||[]).forEach(walk); out.push("\n"); return; }
    if (t==="listItem"){ out.push("- "); (n.content||[]).forEach(walk); out.push("\n"); return; }
    (n.content||[]).forEach(walk);
  }
  walk(node);
  return out.join("").replace(/\n{3,}/g,"\n\n").trim();
}
function escRe(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
function grabLine(label,text){ const re=new RegExp(`^[*\\s]*${escRe(label)}[*\\s]*:\\s*(.+)$`,'im'); const m=re.exec(text); return m?m[1].trim():null; }
function grabSection(startLabel,nextLabels,text){
  const header=new RegExp(`^[*\\s]*${escRe(startLabel)}[*\\s]*:\\s*$`,'im');
  const m=header.exec(text);
  let startIdx=null;
  if (m){ startIdx=m.index+m[0].length; }
  else {
    const single=new RegExp(`^[*\\s]*${escRe(startLabel)}[*\\s]*:\\s*(.+)$`,'im');
    const m2=single.exec(text); return m2?m2[1].trim():null;
  }
  let nextPos=text.length;
  const sub=text.slice(startIdx);
  for (const lbl of nextLabels){
    const hdr=new RegExp(`^[*\\s]*${escRe(lbl)}[*\\s]*:\\s*$`,'im');
    const one=new RegExp(`^[*\\s]*${escRe(lbl)}[*\\s]*:\\s*(.+)$`,'im');
    const mHdr=hdr.exec(sub); if (mHdr) nextPos=Math.min(nextPos,startIdx+mHdr.index);
    const mOne=one.exec(sub); if (mOne) nextPos=Math.min(nextPos,startIdx+mOne.index);
  }
  const section=text.slice(startIdx,nextPos).trim();
  return section||null;
}
function uniqJoin(list){ return Array.from(new Set(list.filter(Boolean))).join("\n\n"); }

// For “Mitigation” normalization
function formatMitigation(txt){
  if (!txt) return null;
  const urls=[...txt.matchAll(/https?:\/\/[^\s)>\]]+/g)].map(m=>m[0]);
  const core=txt.replace(/\s*\n\s*/g," ").trim();
  const parts=core.split(/(?<=[.!?])\s+/);
  let out=parts.filter(Boolean).join("\n\n");
  if (urls.length) out+="\n\n"+urls.join("\n");
  return out;
}

// ---------- extractors ----------
// ZAP
function extractZap(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const allUrls=[...text.matchAll(/https?:\/\/[^\s)>\]]+/g)].map(m=>m[0]);

  const endpointsBlock=grabSection("Systems/Endpoints",["Description","Mitigation","References","Site Owner","Reporter"],text);
  const sysUrls=endpointsBlock? [...endpointsBlock.matchAll(/https?:\/\/[^\s)>\]]+/g)].map(m=>m[0]) : allUrls.slice();

  let mainEndpoint=null;
  if (sysUrls.length){ const m=sysUrls[0].match(/^https?:\/\/[^/]+/i); if (m) mainEndpoint=m[0]; }

  const title=grabLine("Title",text);
  const severity=grabLine("Severity",text);
  const dueDate=grabLine("Due Date",text);
  const cve=grabLine("CVE",text);
  const pet=grabLine("Product/Engagement/Test",text);
  const cweM=text.match(/\bCWE-(\d+)\b/);
  let cwe=cweM?`CWE-${cweM[1]}`:null;
  if (cwe) cwe+=` (https://cwe.mitre.org/data/definitions/${cweM[1]}.html)`;
  let siteOwner=grabLine("Site Owner",text);
  if (siteOwner) siteOwner=siteOwner.replace(/^\*+|\*+$/g,"").trim();

  const descriptionSec=grabSection("Description",["Mitigation","References","Site Owner","Reporter"],text);
  const mitigationSec =grabSection("Mitigation", ["References","Site Owner","Reporter","Description"],text);
  const referencesSec =grabSection("References", ["Site Owner","Reporter","Description","Mitigation"],text);

  return {
    Title: cleanText(title||""),
    Severity: cleanText(severity||""),
    "Due Date": cleanText(dueDate||""),
    CWE: cleanText(cwe||""),
    CVE: cleanText(cve||""),
    "Product/Engagement/Test": cleanText(pet||""),
    "Systems/Endpoints": sysUrls.length? sysUrls.join("\n") : null,
    Description: descriptionSec? cleanText(descriptionSec): null,
    Mitigation: formatMitigation(mitigationSec),
    References: referencesSec? cleanText(referencesSec): null,
    "Site Owner": siteOwner? cleanText(siteOwner): null,
    "Main Endpoint": mainEndpoint||null,
  };
}

// Trufflehog
function extractTrufflehog(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const title      = grabLine("Title", text);
  const cve        = grabLine("CVE", text);
  const sourceFile = grabLine("Source File", text);
  const repoOwner  = grabLine("Repo Owner", text);
  const cweM=text.match(/\bCWE-(\d+)\b/); const cwe = cweM ? `CWE-${cweM[1]} (https://cwe.mitre.org/data/definitions/${cweM[1]}.html)` : null;
  const references = grabSection("References", ["Mitigation","Impact","Repo Owner","Source File","CWE","CVE","Title"], text);
  const mitigation = grabSection("Mitigation",  ["References","Impact","Repo Owner","Source File","CWE","CVE","Title"], text);
  const impact     = grabSection("Impact",      ["References","Mitigation","Repo Owner","Source File","CWE","CVE","Title"], text);

  return {
    Title: cleanText(title||""),
    CWE: cleanText(cwe||""),
    CVE: cleanText(cve||""),
    "Source File": cleanText(sourceFile||""),
    "Repo Owner": cleanText(repoOwner||""),
    References: cleanText(references||""),
    Mitigation: formatMitigation(mitigation||""),
    Impact: cleanText(impact||""),
  };
}

// SecurityHub
function extractSecurityHub(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const acct   = (text.match(/\*\*?AwsAccountId:\*\*?\s*(\d+)/i)||[])[1] || null;
  const genId  = (text.match(/\*\*?Generator ID:\*\*?\s*(security-control\/[a-z0-9.]+)/i)||[])[1] || null;
  const region = (text.match(/\*\*?Region:\*\*?\s*([\w-]+)/i)||[])[1] || null;
  const title  = (text.match(/\*Title\*:\s*\[(.*?)\s*-\s*Resource:/i)||[])[1] || null;
  const sev    = (text.match(/\*?Severity:\*?\s*(.*?)\n/i)||[])[1] || null;
  const arn    = (text.match(/\*\*AWS Finding ARN:\*\*\s*(arn:[^\s]+)\s*/i)||[])[1] || null;

  const impact = grabSection("Impact", ["References","Mitigation","Repo Owner","Source File","CWE","CVE","Title"], text);
  const refs   = grabSection("References", ["Impact","Mitigation","Repo Owner","Source File","CWE","CVE","Title"], text);
  const dor    = (text.match(/\*Description\*:\s*([\s\S]*?)\n\*\*AWS Finding ARN:\*\*/i)||[])[1] || null;

  let cwe = (text.match(/\bCWE-(\d+)\b/)||[])[1];
  cwe = cwe ? `CWE-${cwe} (https://cwe.mitre.org/data/definitions/${cwe}.html)` : null;

  return {
    Title: cleanText(title||""),
    Severity: cleanText(sev||""),
    Region: cleanText(region||""),
    "AWS Finding ARN": cleanText(arn||""),
    "AwsAccountId": cleanText(acct||""),
    "Generator ID": cleanText(genId||""),
    Description: cleanText(dor||""),
    Impact: cleanText(impact||""),
    References: cleanText(refs||""),
    CWE: cleanText(cwe||""),
  };
}

// Checkov
function extractCheckov(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const title  = (text.match(/\*Title\*:\s*\[(.*?)\|/i)||[])[1] || null;
  const sev    = (text.match(/\*Severity\*:\s*(.*?)\n/i)||[])[1] || null;
  const cweM   = (text.match(/\bCWE-(\d+)\b/)||[])[1];
  const cwe    = cweM ? `CWE-${cweM} (https://cwe.mitre.org/data/definitions/${cweM}.html)` : null;
  const repo   = (text.match(/Repo\s*Link:\s*(https?:\/\/[^\s]+)/i)||[])[1] || null;
  const owner  = (text.match(/Repo\s*Owner:\s*(\w+)/i)||[])[1] || null;
  const src    = (text.match(/\*Source File\*:\s*(\S+)/i)||[])[1] || null;
  const chkId  = (text.match(/Check\s*Id:\s*([A-Za-z0-9_]+)/i)||[])[1] || null;
  const chkNm  = (text.match(/Check\s*Name:\s*(.*?)\s*Result:/i)||[])[1] || null;
  const refs   = (text.match(/\*References\*:\s*(https?:\/\/[^\s]+(?:\s+https?:\/\/[^\s]+)*)/i)||[])[1] || null;

  return {
    Title: cleanText(title||""),
    Severity: cleanText(sev||""),
    "Repo Link": cleanText(repo||""),
    "Repo Owner": cleanText(owner||""),
    "Source File": cleanText(src||""),
    "Check Id": cleanText(chkId||""),
    "Check Name": cleanText(chkNm||""),
    References: cleanText(refs||""),
    CWE: cleanText(cwe||""),
  };
}

// Prowler
function extractProwler(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const title = (text.match(/\*Title\*:\s*\[(.*?)\|/i)||[])[1] || null;
  const cweM  = (text.match(/\bCWE-(\d+)\b/)||[])[1];
  const cwe   = cweM ? `CWE-${cweM} (https://cwe.mitre.org/data/definitions/${cweM}.html)` : null;
  const refs  = (text.match(/\*References\*:\s*([\s\S]*?)\n\s*\*Reporter/i)||[])[1] || null;
  const acct  = (text.match(/\*\*AWS Account:\*\*\s*(.*?)\s*\|/i)||[])[1] || null;
  const svc   = (text.match(/\*\*AWS Service:\*\*\s*(.*?)\n/i)||[])[1] || null;
  const ctrl  = (text.match(/\*\*Control:\*\*\s*(.*?)\n/i)||[])[1] || null;
  const impact= (text.match(/\*Impact\*:\s*(.*?)\n/i)||[])[1] || null;

  return {
    Title: cleanText(title||""),
    CWE: cleanText(cwe||""),
    References: cleanText(refs||""),
    "AWS Account": cleanText(acct||""),
    "AWS Service": cleanText(svc||""),
    "Control": cleanText(ctrl||""),
    Impact: cleanText(impact||""),
  };
}

// Kubescape
function extractKubescape(description){
  const text=(description && typeof description==="object")? adfToText(description) : (description||"");
  const title = (text.match(/\*Title\*:\s*\[(.*?)\|/i)||[])[1] || null;
  const owner = (text.match(/\*\*Repo Owner:\*\*\s*(.*?)\n/i)||[])[1] || null;
  const repo  = (text.match(/\*\*Repo Link:\*\*\s*(.*?)\n/i)||[])[1] || null;
  const dor   = (text.match(/\*Description\*:\s*([\s\S]*?)\s*\*\*resourceID:\*\*/i)||[])[1] || null;
  const ctrl  = (text.match(/\*\*controlID:\*\*\s*(.*?)\n/i)||[])[1] || null;
  const resid = (text.match(/\*\*resourceID:\*\*\s*(.*?)\n/i)||[])[1] || null;

  let ctrlLink = ctrl ? `${ctrl.trim().toUpperCase()} (https://hub.armosec.io/docs/${ctrl.trim().toLowerCase()})` : null;

  return {
    Title: cleanText(title||""),
    "Repo Owner": cleanText(owner||""),
    "Repo Link": cleanText(repo||""),
    "Description of Risk": cleanText(dor||""),
    "Control ID": cleanText(ctrlLink||""),
    "Resource ID": cleanText(resid||""),
  };
}

// ---------- main (per tool) ----------
const results = [];

if (tool === 'trufflehog') {
  // group: Repo Owner + Source File
  const parsed = items.map(it => {
    const issue = it.json || {};
    const fields = issue.fields || {};
    return { issue, ext: extractTrufflehog(fields.description || null) };
  });

  const groups = new Map();
  for (const {issue, ext} of parsed) {
    const owner = ext["Repo Owner"];
    const file  = ext["Source File"];
    const title = ext["Title"];
    if (owner && file && title) {
      const gk = `${owner}|||${file}`;
      if (!groups.has(gk)) groups.set(gk, { info: ext, keys: [] });
      groups.get(gk).keys.push(issue.key || issue.id);
    }
  }

  for (const [gk,{info,keys}] of groups.entries()) {
    const [owner,file] = gk.split("|||");
    const allCWE=[], allDesc=[], allMit=[], allRef=[];
    for (const {issue,ext} of parsed) {
      if (ext["Repo Owner"]===owner && ext["Source File"]===file) {
        if (ext.CWE) allCWE.push(ext.CWE);
        const parts = [ext.Title, ext.Impact].filter(Boolean).join("\n\n");
        if (parts) allDesc.push(`Ticket ${issue.key}:\n\n${parts}`);
        if (ext.Mitigation) allMit.push(ext.Mitigation);
        if (ext.References) allRef.push(`Ticket ${issue.key}:\n\n${ext.References}`);
      }
    }

    results.push({
      json: {
        summary: `${owner} - ${file}`,
        site_owner_sanitized: owner.replace(/\s+/g,"-"),
        combinedCWEs: uniqJoin(allCWE),                         // → TVI
        combinedDescriptions: uniqJoin(allDesc),                // → Description & DOR
        combinedMitigations: uniqJoin(allMit),
        combinedReferencesWithTicket: uniqJoin(allRef),         // → References
        risk_source: file || "",                                // → Risk Identification Source
        asset_urls: file || "",                                 // → Asset(s) Affected
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}

if (tool === 'securityhub') {
  // group: Account + Generator ID
  const parsed = items.map(it => {
    const issue = it.json || {};
    const fields = issue.fields || {};
    return { issue, ext: extractSecurityHub(fields.description || null) };
  });

  const groups = new Map();
  for (const {issue,ext} of parsed) {
    const acct = ext["AwsAccountId"], gen = ext["Generator ID"];
    if (acct && gen) {
      const gk = `${acct}|||${gen}`;
      if (!groups.has(gk)) groups.set(gk, { info: ext, keys: [] });
      groups.get(gk).keys.push(issue.key || issue.id);
    }
  }

  for (const [gk,{info,keys}] of groups.entries()) {
    const [acct,gen] = gk.split("|||");
    const allCWE=[], allDesc=[], allRefs=[];
    for (const {issue,ext} of parsed) {
      if (ext["AwsAccountId"]===acct && ext["Generator ID"]===gen) {
        if (ext.CWE) allCWE.push(ext.CWE);
        const parts = [ext.Title, ext.Impact].filter(Boolean).join("\n\n");
        if (parts) allDesc.push(`Ticket ${issue.key}:\n\n${parts}`);
        if (ext.References) allRefs.push(`Ticket ${issue.key}:\n\n${ext.References}`);
      }
    }

    results.push({
      json: {
        summary: `${info.Title || ''} - Account-ID: ${acct} - Region: ${info.Region || ''} - Finding: ${gen}`,
        site_owner_sanitized: (acct || "").toString(),
        combinedCWEs: uniqJoin(allCWE),                         // → TVI
        combinedDescriptions: uniqJoin(allDesc),                // → Description & DOR
        combinedReferencesWithTicket: uniqJoin(allRefs),        // → References
        risk_source: info["AWS Finding ARN"] || "",             // → Risk Identification Source
        asset_urls: "",                                         // optional
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}

if (tool === 'checkov') {
  // group: Repo Link + Check Id (stable)
  const parsed = items.map(it => {
    const issue = it.json || {};
    const fields = issue.fields || {};
    return { issue, ext: extractCheckov(fields.description || null) };
  });

  const groups = new Map();
  for (const {issue,ext} of parsed) {
    const repo = ext["Repo Link"], chkId = ext["Check Id"], owner = ext["Repo Owner"];
    if (repo && chkId) {
      const gk = `${repo}|||${chkId}`;
      if (!groups.has(gk)) groups.set(gk, { info: { ...ext, owner }, keys: [] });
      groups.get(gk).keys.push(issue.key || issue.id);
    }
  }

  for (const [gk,{info,keys}] of groups.entries()) {
    const [repo, chkId] = gk.split("|||");
    const allCWE=[], allDesc=[], allRefs=[];
    for (const {issue,ext} of parsed) {
      if (ext["Repo Link"]===repo && ext["Check Id"]===chkId) {
        if (ext.CWE) allCWE.push(ext.CWE);
        const parts = [ext["Check Name"] || info["Title"], info["Severity"]].filter(Boolean).join("\n\n");
        if (parts) allDesc.push(`Ticket ${issue.key}:\n\n${parts}`);
        if (ext.References) allRefs.push(`Ticket ${issue.key}:\n\n${ext.References}`);
      }
    }

    results.push({
      json: {
        summary: `${info["Repo Owner"] || 'Repo'} - ${info["Check Name"] || chkId}`,
        site_owner_sanitized: (info["Repo Owner"] || "").replace(/\s+/g,"-"),
        combinedCWEs: uniqJoin(allCWE),                         // → TVI
        combinedDescriptions: uniqJoin(allDesc),
        combinedReferencesWithTicket: uniqJoin(allRefs),
        risk_source: repo || "",                                // → Risk Identification Source
        asset_urls: info["Source File"] || "",                  // → Asset(s) Affected
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}

if (tool === 'prowler') {
  // group: AWS Account + Control
  const parsed = items.map(it => {
    const issue = it.json || {};
    const fields = issue.fields || {};
    return { issue, ext: extractProwler(fields.description || null) };
  });

  const groups = new Map();
  for (const {issue,ext} of parsed) {
    const acct = ext["AWS Account"], ctrl = ext["Control"];
    if (acct && ctrl) {
      const gk = `${acct}|||${ctrl}`;
      if (!groups.has(gk)) groups.set(gk, { info: ext, keys: [] });
      groups.get(gk).keys.push(issue.key || issue.id);
    }
  }

  for (const [gk,{info,keys}] of groups.entries()) {
    const [acct, ctrl] = gk.split("|||");
    const allCWE=[], allDesc=[], allRefs=[];
    for (const {issue,ext} of parsed) {
      if (ext["AWS Account"]===acct && ext["Control"]===ctrl) {
        if (ext.CWE) allCWE.push(ext.CWE);
        if (ext.Impact) allDesc.push(`Ticket ${issue.key}:\n\n${ext.Impact}`);
        if (ext.References) allRefs.push(`Ticket ${issue.key}:\n\n${ext.References}`);
      }
    }

    results.push({
      json: {
        summary: `Prowler Alert - ${acct} - ${ctrl}`,
        site_owner_sanitized: (acct || "").toString(),
        combinedCWEs: uniqJoin(allCWE),                         // → TVI
        combinedDescriptions: uniqJoin(allDesc),
        combinedReferencesWithTicket: uniqJoin(allRefs),
        risk_source: info["AWS Service"] || "",                 // → Risk Identification Source
        asset_urls: "",                                         // optional
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}

if (tool === 'kubescape') {
  // group: Control ID + Repo Link (stable)
  const parsed = items.map(it => {
    const issue  = it.json || {};
    const fields = issue.fields || {};
    return { issue, ext: extractKubescape(fields.description || null) };
  });

  const groups = new Map();
  for (const { issue, ext } of parsed) {
    const ctrl = ext["Control ID"];
    const repo = ext["Repo Link"];
    if (ctrl && repo) {
      const gk = `${ctrl}|||${repo}`;
      if (!groups.has(gk)) groups.set(gk, { info: ext, keys: [] });
      groups.get(gk).keys.push(issue.key || issue.id);
    }
  }

  // single-line + cap to keep Jira summary tidy
  const oneLineCap = (s, max = 160) => {
    if (!s) return "";
    const flat = String(s).replace(/\s+/g, " ").trim();
    return flat.length > max ? flat.slice(0, max - 3) + "..." : flat;
  };

  for (const [gk, { info, keys }] of groups.entries()) {
    const [ctrl, repo] = gk.split("|||");

    // Build deduped, ticket-free content for Kubescape
    const descOnly = [];     // pure descriptions (no ticket prefixes)
    const controls = [];     // pure control IDs (mitigating controls), no ticket prefixes
    const tviList  = [];     // also keep control IDs here for TVI

    for (const { issue, ext } of parsed) {
      if (ext["Control ID"] === ctrl && ext["Repo Link"] === repo) {
        if (ext["Description of Risk"]) descOnly.push(ext["Description of Risk"]);
        if (ext["Control ID"]) { controls.push(ext["Control ID"]); tviList.push(ext["Control ID"]); }
      }
    }

    // SUMMARY: "Kubescape Alert - <repo> - <combined description (once)>" (no Ticket / no Control ID)
    const combinedDescOnce = uniqJoin(descOnly);
    const summaryTail      = oneLineCap(combinedDescOnce || info["Title"] || "");
    const summary          = `Kubescape Alert - ${repo} - ${summaryTail}`;

    results.push({
      json: {
        summary,
        site_owner_sanitized: (info["Repo Owner"] || "").replace(/\s+/g, "-"),

        // Control IDs remain in TVI as requested
        combinedCWEs: uniqJoin(tviList),

        // Description of Risk: deduped & ticket-free
        combinedDescriptions: uniqJoin(descOnly),

        // Mitigating Controls: use Control IDs here too, deduped & ticket-free
        combinedReferencesWithTicket: uniqJoin(controls),

        risk_source: info["Repo Link"] || "",     // Risk Identification Source
        asset_urls: info["Resource ID"] || "",    // Asset(s) Affected
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}


