    const issue=it.json||{}, fields=issue.fields||{}, desc=fields.description||null;
    const ext=extractZap(desc);
    const ep=ext["Main Endpoint"], owner=ext["Site Owner"];
    if (ep && owner){ const k=`${ep}|||${owner}`; if (!groups.has(k)) groups.set(k,{info:ext,keys:[]}); groups.get(k).keys.push(issue.key||issue.id); }
  }

  for (const [k,{info,keys}] of groups.entries()){
    const [ep,owner]=k.split("|||");
    const allCWE=[], allDesc=[], allMit=[], allRef=[];
    for (const it of items){
      const issue=it.json||{}, f=issue.fields||{}, ext=extractZap(f.description||null);
      if (ext["Main Endpoint"]===ep && ext["Site Owner"]===owner){
        if (ext.CWE) allCWE.push(ext.CWE);
        if (ext.Description) allDesc.push(`Ticket ${issue.key}:\n\n${ext.Description}`);
        if (ext.Mitigation)  allMit.push(ext.Mitigation);
        if (ext.References)  allRef.push(`Ticket ${issue.key}:\n\n${ext.References}`);
      }
    }
    results.push({
      json:{
        summary: `${ep} - ${owner}`,
        site_owner_sanitized: owner.replace(/\s+/g,"-"),
        combinedCWEs: uniqJoin(allCWE),
        combinedDescriptions: uniqJoin(allDesc),
        combinedMitigations: uniqJoin(allMit),
        combinedReferencesWithTicket: uniqJoin(allRef),
        risk_source: info["Product/Engagement/Test"] || "",
        asset_urls: info["Systems/Endpoints"] || "",
        sourceIssueKeys: keys
      }
    });
  }
  return results;
}

// Create Update Payload (seed Description only if blank; cap refs; carry keys; multi-tool incl. Kubescape)
// In #1: issues from "Get an issue" (RRD)
// In #2: optional Set { forceUpdate: true }
// Reads grouped data from node named EXACTLY "Decide_Update/Create"

const FORCE_UPDATE_DEFAULT = false;
const toggleInput = $input.all(1);
const FORCE_UPDATE = (toggleInput[0]?.json?.forceUpdate ?? FORCE_UPDATE_DEFAULT) === true;

const existingItems = $input.all();
const decideItems   = ($items("Decide_Update/Create") || []).map(i => i.json || {});

const byExistingKey = new Map();
const bySummary     = new Map();
for (const d of decideItems) {
  if (d?.existingKey) byExistingKey.set(String(d.existingKey), d);
  if (d?.summary)     bySummary.set(String(d.summary), d);
}

// ---------- helpers ----------
const sameText = (a, b) => String(a ?? "").trim() === String(b ?? "").trim();

const sameArray = (a = [], b = []) => {
  if (a.length !== b.length) return false;
  const A = [...a].sort(), B = [...b].sort();
  for (let i = 0; i < A.length; i++) if (A[i] !== B[i]) return false;
  return true;
};

const combineBlocks = (a, b) => {
  const A = String(a || "").split(/\n{2,}/).map(s => s.trim()).filter(Boolean);
  const B = String(b || "").split(/\n{2,}/).map(s => s.trim()).filter(Boolean);
  const set = new Set([...A, ...B]);
  return Array.from(set).join("\n\n");
};

const includeText = (obj, key, newVal, oldVal) => {
  if (!newVal) return; // don't wipe Jira
  if (FORCE_UPDATE || !sameText(newVal, oldVal)) obj[key] = newVal;
};

// Canonical labels (includes Kubescape)
function normalizeLabel(s) {
  if (!s) return null;
  const canon = {
    trufflehog: "Trufflehog",
    zaproxy: "Zaproxy",
    securityhub: "SecurityHub",
    checkov: "Checkov",
    prowler: "Prowler",
    kubescape: "Kubescape",
  };
  const t = String(s).trim(); if (!t) return null;
  const key = t.toLowerCase();
  return canon[key] || t;
}

function uniqLabelsCaseInsensitive(arr) {
  const seen = new Set(), out = [];
  for (const raw of arr) {
    const norm = normalizeLabel(raw);
    if (!norm) continue;
    const k = norm.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k); out.push(norm);
  }
  return out;
}

// Detect tool by summary/content (adds Kubescape)
function toolLabelForGroup(grp) {
  const sum = String(grp?.summary || "");
  const desc = String(grp?.combinedDescriptions || "");
  const refs = String(grp?.combinedReferencesWithTicket || "");
  const tvi  = String(grp?.combinedCWEs || "");

  if (/^\s*Kubescape\s*Alert/i.test(sum) || /kubescape/i.test(desc) || /kubescape/i.test(refs)) return "Kubescape";
  if (/^\s*Prowler\s*Alert/i.test(sum) || /prowler/i.test(desc) || /prowler/i.test(refs)) return "Prowler";
  if (/^\s*https?:\/\//i.test(sum)) return "Zaproxy";
  if (/securityhub/i.test(sum) || /security-control\//i.test(desc) || /security-control\//i.test(refs)) return "SecurityHub";
  if (/ckv[-_]/i.test(desc) || /checkov/i.test(sum) || /checkov/i.test(refs)) return "Checkov";
  if (/trufflehog/i.test(desc) || /trufflehog/i.test(refs)) return "Trufflehog";
  return "Trufflehog";
}

// Soft-cap to Jira’s CF text limit (32,767)
function capText(str, max = 32767) {
  const s = String(str || "");
  if (s.length <= max) return { text: s, truncated: false };
  const paras = s.split(/\n{2,}/);
  let cur = "";
  for (const p of paras) {
    const trial = cur ? (cur + "\n\n" + p) : p;
    if (trial.length + 3 > max) break;
    cur = trial;
  }
  if (!cur) return { text: s.slice(0, max - 3) + "...", truncated: true };
  return { text: cur + "...", truncated: true };
}

// Description template (seed only when Jira Description is blank)
const DESC_TEMPLATE = "Likelihood/Probability:\nImpact/Severity:\nResidual Risk:";

const out = [];

for (const it of existingItems) {
  const ex      = it.json || {};
  const key     = ex.key;
  const fields  = ex.fields || {};
  const summary = fields.summary || "";

  const grp = byExistingKey.get(String(key)) || bySummary.get(String(summary));
  if (!grp) continue;

  // current Jira
  const exDesc   = fields.description || "";
  const exDOR    = fields.customfield_10066 || ""; // Description of Risk
  const exRefs   = fields.customfield_10067 || ""; // References
  const exRisk   = fields.customfield_10063 || ""; // Risk Identification Source
  const exAssets = fields.customfield_10065 || ""; // Asset(s) Affected
  const exTVI    = fields.customfield_10064 || ""; // Threat & Vulnerability Info
  const exLabels = fields.labels || [];

  // new merged (note: Description is handled specially below)
  const newDOR     = combineBlocks(exDOR,  grp.combinedDescriptions || "");
  const refsMerged = combineBlocks(exRefs,  grp.combinedReferencesWithTicket || "");
  const newRisk    = grp.risk_source || "";
  const newAssets  = combineBlocks(exAssets, grp.asset_urls || "");
  const newTVI     = combineBlocks(exTVI, grp.combinedCWEs || "");

  // Seed Description ONLY if Jira's Description is blank; otherwise leave it as-is
  const shouldSeedDesc = String(exDesc || "").trim().length === 0;
  const descToWrite    = shouldSeedDesc ? DESC_TEMPLATE : null; // null means "don't touch"

  // CAP References to avoid 400
  const refsSafe   = capText(refsMerged, 32767).text;

  // labels
  const ownerLabel = String(grp.site_owner_sanitized || "").trim() || null;
  const toolLabel  = toolLabelForGroup(grp);
  const newLabels  = uniqLabelsCaseInsensitive([ ...exLabels, ownerLabel, toolLabel ]);

  // change detection
  let changed = false;
  if (shouldSeedDesc && !sameText(DESC_TEMPLATE, exDesc)) changed = true; // only consider desc if we're seeding
  if (!sameText(newDOR,  exDOR))  changed = true;
  if (!sameText(refsSafe, exRefs)) changed = true; // compare with capped refs
  if (newRisk && !sameText(newRisk, exRisk)) changed = true;
  if (!sameText(newAssets, exAssets)) changed = true;
  if (!sameText(newTVI, exTVI)) changed = true;
  if (!sameArray(newLabels, exLabels)) changed = true;

  if (!FORCE_UPDATE && !changed) continue;

  // build update
  const updateFields = {};
  if (shouldSeedDesc) {
    includeText(updateFields, "description", descToWrite, exDesc); // seed template
  } // else: leave Description untouched, by design

  includeText(updateFields, "customfield_10066",  newDOR,    exDOR);
  includeText(updateFields, "customfield_10067",  refsSafe,  exRefs); // capped
  includeText(updateFields, "customfield_10063",  newRisk,   exRisk);
  includeText(updateFields, "customfield_10065",  newAssets, exAssets);
  includeText(updateFields, "customfield_10064",  newTVI,    exTVI);

  if (FORCE_UPDATE || !sameArray(newLabels, exLabels)) {
    updateFields.labels = newLabels;
  }

  if (Object.keys(updateFields).length === 0) continue;

  // carry-through metadata for downstream (e.g., link back to sources)
  const carriedSourceKeys = Array.isArray(grp.sourceIssueKeys) ? grp.sourceIssueKeys : [];

  out.push({
    json: {
      issueKey: key,          // used by Jira Update node
      fields: updateFields,   // used by Jira Update node

      // carry-through meta (not read by Jira)
      rrdKey: key,
      sourceIssueKeys: carriedSourceKeys,
      toolLabel,
      summary
    }
  });
}

return out;

// Decide Update/Create (ROBUST)
// - Groups from "Tag Index" (else falls back to $input)
// - RRD issues from a Jira node named EXACTLY "Check RRD"
// - Emits: { ...group, exists, existingKey }

function got(name) {
  try {
    const arr = $items(name);
    return Array.isArray(arr) ? arr.map(i => i.json || {}) : [];
  } catch { return []; }
}

const groups = got("Tag Index").length ? got("Tag Index") : ($input.all() || []).map(i => i.json || {});
const searchIssues = got("Check RRD")
  .filter(it => (it.key || it.id) && (it.fields?.summary || it.summary));

const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
const newer = (a, b) => {
  const an = Number(String(a.id || '').replace(/\D/g, ''));
  const bn = Number(String(b.id || '').replace(/\D/g, ''));
  return (!Number.isNaN(an) && !Number.isNaN(bn)) ? (an >= bn ? a : b) : a;
};

// Exact-summary lookup (normalized)
const bySummary = new Map();
for (const issue of searchIssues) {
  const s = issue.fields?.summary ?? issue.summary ?? '';
  const n = norm(s);
  if (!n) continue;
  const prev = bySummary.get(n);
  bySummary.set(n, prev ? newer(issue, prev) : issue);
}

// --- Robust tokenization ---
// We split on " - " into segments and match all non-empty tokens against candidates.
// Special cases:
//  - ZAP: left is URL → reduce to host token
//  - Prowler: summary starts with "Prowler Alert - " → ignore that banner segment
function segmentsFromSummary(summary) {
  const raw = String(summary || '');
  const parts = raw.split(/\s-\s/).map(p => p.trim()).filter(Boolean);

  // ZAP: if first part looks like URL, reduce to host
  if (/^https?:\/\//i.test(parts[0] || '')) {
    const host = parts[0].replace(/^https?:\/\//i, '').replace(/\/.*$/, '');
    parts[0] = host;
  }

  // Prowler: drop the banner "Prowler Alert"
  if (/^prowler\s*alert$/i.test(parts[0] || '')) {
    parts.shift(); // remove "Prowler Alert"
  }

  // Kubescape: drop the banner "Kubescape Alert"
  if (/^kubescape\s*alert$/i.test(parts[0] || '')) {
    parts.shift();
  }

  // Split remaining parts further on whitespace to be resilient, but keep short phrases together
  // Heuristic: emit tokens that are at least 2 chars, ignoring punctuation-only
  const tokens = [];
  for (const p of parts) {
    const t = p.replace(/[^\p{L}\p{N}\-_/.: ]+/gu, ' ').trim(); // keep typical chars
    const bits = t.split(/\s+/).filter(Boolean);
    // prefer the whole segment as a token, but add select sub-bits for robustness
    if (t) tokens.push(t.toLowerCase());
    for (const b of bits) {
      if (b.length >= 2) tokens.push(b.toLowerCase());
    }
  }

  // De-dup
  return Array.from(new Set(tokens));
}

function fuzzyFind(summary) {
  const toks = segmentsFromSummary(summary);
  if (!toks.length) return null;

  // Score each candidate by how many tokens it contains; pick the newest among top score ties
  let best = null;
  let bestScore = -1;

  for (const issue of searchIssues) {
    const s = (issue.fields?.summary ?? issue.summary ?? '').toLowerCase();
    if (!s) continue;

    let score = 0;
    for (const tk of toks) {
      if (s.includes(tk)) score++;
    }

    if (score > bestScore) {
      best = issue; bestScore = score;
    } else if (score === bestScore && best) {
      best = newer(issue, best);
    }
  }

  // Require at least 2 token hits to avoid spurious matches (1 is too weak)
  if (best && bestScore >= Math.min(2, toks.length)) return best;
  return null;
}

// Build output
let out = groups.map(g => {
  const exact = bySummary.get(norm(g.summary));
  const hit = exact || fuzzyFind(g.summary);
  const existingKey = hit ? (hit.key || hit.id || null) : null;
  const exists = !!existingKey;
  return { json: { ...g, exists, existingKey } };
});

// Helpful debug when your RRD query returned nothing
if (!searchIssues.length) {
  out = out.map(it => ({
    json: { ...it.json, _debug: "No items from 'Check RRD'. Verify node name & JQL; enable 'Always Output Data' and set a high limit." }
  }));
}

return out;

// JQL Builder — supports zaproxy, trufflehog, securityhub, checkov, kubescape
const cfg = ($node["Config"]?.json) || {};
const tool          = String(cfg.tool || "zaproxy").toLowerCase();
const requireLabel  = (cfg.requireLabel ?? true);
const labelOverride = cfg.labelOverride;
const rrdProject    = String(cfg.rrdProject || "RRD");
const sinceDays     = cfg.sinceDays;
const statusCat     = cfg.statusCategory;
const extraJql      = (cfg.extraJql || "").trim();

const esc = (s) => String(s || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');

const labelForTool = (t) => {
  if (labelOverride) return labelOverride;
  if (t === "trufflehog")  return "Trufflehog";
  if (t === "securityhub") return "SecurityHub";
  if (t === "checkov")     return "Checkov";
  if (t === "kubescape")   return "Kubescape";
  return "Zaproxy";
};

function appendCommon(parts, t) {
  if (requireLabel) parts.push(`labels in ("${esc(labelForTool(t))}")`);
  if (sinceDays)    parts.push(`updated >= -${parseInt(sinceDays,10)}d`);
  if (statusCat)    parts.push(`statusCategory != ${esc(statusCat)}`);
  if (extraJql)     parts.push(`(${extraJql})`);
}

function jqlForZap(summary) {
  const m = String(summary || "").match(/^\s*(https?:\/\/[^ ]+)\s*-\s*(.+)\s*$/i);
  const endpoint = m ? m[1] : String(summary || "");
  const owner    = m ? m[2] : "";
  const host     = endpoint.replace(/^https?:\/\//i, "").replace(/\/.*$/, "");

  const parts = [
    `project = ${esc(rrdProject)}`,
    `(summary ~ "${esc(`${host}${owner ? ` - ${owner}` : ""}`)}" OR (summary ~ "${esc(host)}"${owner ? ` AND summary ~ "${esc(owner)}"` : ""}))`,
  ];
  appendCommon(parts, "zaproxy");
  return { jql: parts.join(" AND ") + " ORDER BY created DESC", parts, labelUsed: labelForTool("zaproxy") };
}

function jqlForTrufflehog(summary) {
  const m = String(summary || "").match(/^\s*(.+?)\s*-\s*(.+)\s*$/);
  const owner = m ? m[1] : String(summary || "");
  const file  = m ? m[2] : "";

  const parts = [
    `project = ${esc(rrdProject)}`,
    `(summary ~ "${esc(`${owner} - ${file}`)}" OR (summary ~ "${esc(owner)}"${file ? ` AND summary ~ "${esc(file)}"` : ""}))`,
  ];
  appendCommon(parts, "trufflehog");
  return { jql: parts.join(" AND ") + " ORDER BY created DESC", parts, labelUsed: labelForTool("trufflehog") };
}

function jqlForSecurityHub(summary) {
  const raw = String(summary || "");
  const acct    = (raw.match(/Account-ID:\s*(\d{6,})/i)   || [])[1] || "";
  const region  = (raw.match(/Region:\s*([\w-]+)/i)       || [])[1] || "";
  const finding = (raw.match(/Finding:\s*([^\s]+)\s*$/i)  || [])[1] || "";

  const tokens = [];
  if (acct)    tokens.push(`summary ~ "${esc(acct)}"`);
  if (finding) tokens.push(`summary ~ "${esc(finding)}"`);
  if (region)  tokens.push(`summary ~ "${esc(region)}"`);
  if (!tokens.length) tokens.push(`summary ~ "${esc(raw)}"`);

  const parts = [
    `project = ${esc(rrdProject)}`,
    `(${tokens.join(" AND ")})`,
  ];
  appendCommon(parts, "securityhub");
  return { jql: parts.join(" AND ") + " ORDER BY created DESC", parts, labelUsed: labelForTool("securityhub") };
}

// Checkov → "<Repo Owner> - <Check Name>"
function jqlForCheckov(summary) {
  const m = String(summary || "").match(/^\s*(.+?)\s*-\s*(.+)\s*$/);
  const owner = m ? m[1] : String(summary || "");
  const check = m ? m[2] : "";

  const parts = [
    `project = ${esc(rrdProject)}`,
    `(summary ~ "${esc(`${owner} - ${check}`)}" OR (summary ~ "${esc(owner)}"${check ? ` AND summary ~ "${esc(check)}"` : ""}))`,
  ];
  appendCommon(parts, "checkov");
  return { jql: parts.join(" AND ") + " ORDER BY created DESC", parts, labelUsed: labelForTool("checkov") };
}

// Kubescape → we target the repo link + (optionally) a stable token like Control ID
// Your grouped summary will be "Kubescape Alert - <repo_link> - <something>"
// so we at least require the repo_link; the “something” can change over time.
function jqlForKubescape(summary) {
  const raw = String(summary || "");
  // Try to extract the repo link if in the standard "Kubescape Alert - repo - ..." format
  let repo = "";
  const m = raw.match(/^\s*Kubescape\s*Alert\s*-\s*(.+?)\s*-\s*(.+)\s*$/i);
  if (m) {
    repo = m[1].trim();
  } else {
    // Fallback: just use the big summary text (safe-quoted)
    repo = raw;
  }

  const parts = [
    `project = ${esc(rrdProject)}`,
    `(summary ~ "${esc(repo)}")`,
  ];
  appendCommon(parts, "kubescape");
  return { jql: parts.join(" AND ") + " ORDER BY created DESC", parts, labelUsed: labelForTool("kubescape") };
}

const out = items.map(it => {
  const summary = it.json?.summary ?? it.json?.fields?.summary ?? "";
  let built;
  if (tool === "trufflehog")       built = jqlForTrufflehog(summary);
  else if (tool === "securityhub") built = jqlForSecurityHub(summary);
  else if (tool === "checkov")     built = jqlForCheckov(summary);
  else if (tool === "kubescape")   built = jqlForKubescape(summary);
  else                             built = jqlForZap(summary);

  return {
    json: {
      ...it.json,
      jql: built.jql,
      jqlParts: built.parts,
      labelUsed: built.labelUsed,
      _builder: { tool, requireLabel, rrdProject, sinceDays, statusCat, extraJql, labelOverride }
    }
  };
});

return out;

// Build JQL from Config (expects this node to receive one item with your config)
// Supported tools: "zaproxy", "trufflehog", "securityhub"

const cfg = $json;
const esc = (s='') => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

const defaults = {
  zaproxy:    ({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'Zaproxy')}"`,
  trufflehog: ({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'Trufflehog')}"`,
  securityhub:({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'SEC_HUB')}"`,
  checkov:({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'Checkov')}"`,
  prowler:({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'Prowler')}"`,
  kubescape:({ sourceProject, label }) => `project = ${esc(sourceProject)} AND labels = "${esc(label || 'Kubescape')}"`,
};

let jql = (cfg.jqlOverride || '').trim();
if (!jql) {
  const maker = defaults[cfg.tool] || defaults.zaproxy;
  jql = maker(cfg);
}
if (cfg.sinceDays)      jql += ` AND updated >= -${parseInt(cfg.sinceDays, 10)}d`;
if (cfg.statusCategory) jql += ` AND statusCategory != ${esc(cfg.statusCategory)}`;
if (cfg.extraJql)       jql += ` AND (${cfg.extraJql})`;

return [{ json: { ...cfg, jql } }];
